	protected void emitFindAllCarrierService( CarrierService entity ) {
		LOGGER.info("handling emitFindAllCarrierService" );
		
	    queryUpdateEmitter.emit(FindAllCarrierServiceQuery.class,
	                            query -> true,
	                            entity);
	}

